/**
 * tests/cases.test.js — NETRA-DR Module 3 Screening Case Test Suite
 *
 * Verifies all required scenarios for Module 3 (Screening Case Creation):
 *   1.  Authenticated technician can create a case
 *   2.  Authenticated admin can create a case
 *   3.  Doctor cannot create a case (403 Forbidden)
 *   4.  Unauthenticated request is rejected (401 Unauthorized)
 *   5.  Missing patient reference is rejected (400 Bad Request)
 *   6.  Case ID is generated by the backend ('case_<uuid>')
 *   7.  createdBy comes from authenticated user (spoofing prevented)
 *   8.  Newly created case has status "created"
 *   9.  GET /api/cases works for authorized roles (technician, doctor, admin)
 *  10.  GET /api/cases/:id returns an existing case
 *  11.  GET /api/cases/:id returns 404 for nonexistent case
 *  12.  PATCH /api/cases/:id validates allowed fields
 *  13.  Protected fields (id, createdBy, createdAt, status) cannot be arbitrarily changed (400)
 *  14.  Attempting to set non-'created' status during creation returns 400
 *  15.  PATCH nonexistent case returns 404
 *  16.  PATCH with empty body returns 400
 *  17.  Safe case responses never expose sensitive data or fake AI fields
 */

'use strict';

const { test, describe, before, after, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const app = require('../src/app');
const UserModel = require('../src/models/user.model');
const CaseModel = require('../src/models/case.model');
const { ROLES } = require('../src/config/roles');

describe('NETRA-DR Module 3 — Screening Case Creation Tests', () => {
  let server;
  let baseUrl;

  let technicianToken;
  let technicianUser;
  let doctorToken;
  let doctorUser;
  let adminToken;
  let adminUser;

  const users = {
    technician: {
      name: 'Tech Alpha',
      email: 'tech.alpha@netradr.org',
      password: 'TechAlphaPassword2026!',
      role: ROLES.TECHNICIAN,
    },
    doctor: {
      name: 'Dr. Retina',
      email: 'dr.retina@netradr.org',
      password: 'DoctorRetinaPass2026!',
      role: ROLES.DOCTOR,
    },
    admin: {
      name: 'Admin Boss',
      email: 'admin.boss@netradr.org',
      password: 'AdminBossPass2026!',
      role: ROLES.ADMIN,
    },
  };

  /**
   * Helper: Register user and return login token + user object
   */
  const registerAndLogin = async (userData) => {
    const regRes = await fetch(`${baseUrl}/api/auth/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(userData),
    });
    const regBody = await regRes.json();
    assert.strictEqual(regRes.status, 201, `Failed to register ${userData.email}`);

    const loginRes = await fetch(`${baseUrl}/api/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: userData.email, password: userData.password }),
    });
    const loginBody = await loginRes.json();
    assert.strictEqual(loginRes.status, 200, `Failed to login ${userData.email}`);

    return { token: loginBody.token, user: regBody.user };
  };

  before(async () => {
    await UserModel.clear();
    await CaseModel.clear();

    await new Promise((resolve) => {
      server = app.listen(0, '127.0.0.1', () => {
        const port = server.address().port;
        baseUrl = `http://127.0.0.1:${port}`;
        resolve();
      });
    });

    const techAuth   = await registerAndLogin(users.technician);
    technicianToken  = techAuth.token;
    technicianUser   = techAuth.user;

    const docAuth    = await registerAndLogin(users.doctor);
    doctorToken      = docAuth.token;
    doctorUser       = docAuth.user;

    const admAuth    = await registerAndLogin(users.admin);
    adminToken       = admAuth.token;
    adminUser        = admAuth.user;
  });

  after(async () => {
    if (server) {
      await new Promise((resolve) => server.close(resolve));
    }
  });

  beforeEach(async () => {
    await CaseModel.clear();
  });

  // --------------------------------------------------------------------------
  // 1. Authenticated technician can create a case
  // --------------------------------------------------------------------------
  test('1. Authenticated technician can create a case: POST /api/cases returns 201', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        patientId: 'PAT-001',
        notes: 'Routine diabetes eye exam',
      }),
    });

    assert.strictEqual(res.status, 201);
    const body = await res.json();
    assert.strictEqual(body.status, 'success');
    assert.strictEqual(body.success, true);
    assert.ok(body.case);
    assert.strictEqual(body.case.patientId, 'PAT-001');
    assert.strictEqual(body.case.notes, 'Routine diabetes eye exam');
    assert.strictEqual(body.case.status, 'created');
  });

  // --------------------------------------------------------------------------
  // 2. Authenticated admin can create a case
  // --------------------------------------------------------------------------
  test('2. Authenticated admin can create a case: POST /api/cases returns 201', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${adminToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        patientId: 'PAT-ADM-99',
      }),
    });

    assert.strictEqual(res.status, 201);
    const body = await res.json();
    assert.strictEqual(body.status, 'success');
    assert.strictEqual(body.case.patientId, 'PAT-ADM-99');
    assert.strictEqual(body.case.createdBy, adminUser.id);
  });

  // --------------------------------------------------------------------------
  // 3. Doctor cannot create a case (403 Forbidden)
  // --------------------------------------------------------------------------
  test('3. Doctor cannot create a case: POST /api/cases returns 403 Forbidden', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${doctorToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        patientId: 'PAT-DOC-01',
      }),
    });

    assert.strictEqual(res.status, 403);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.strictEqual(body.code, 403);
    assert.match(body.message, /access denied/i);
  });

  // --------------------------------------------------------------------------
  // 4. Unauthenticated request is rejected (401 Unauthorized)
  // --------------------------------------------------------------------------
  test('4. Unauthenticated request is rejected: POST /api/cases returns 401', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ patientId: 'PAT-NOAUTH' }),
    });

    assert.strictEqual(res.status, 401);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.strictEqual(body.code, 401);
  });

  // --------------------------------------------------------------------------
  // 5. Missing patient reference is rejected (400 Bad Request)
  // --------------------------------------------------------------------------
  test('5. Missing patient reference is rejected: POST /api/cases returns 400', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        notes: 'Forgot the patient id',
      }),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.strictEqual(body.code, 400);
    assert.match(body.message, /patient reference/i);
  });

  test('5b. Empty string patient reference is rejected with 400', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        patientId: '   ',
      }),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /patient reference/i);
  });

  // --------------------------------------------------------------------------
  // 6. Case ID is generated by the backend
  // --------------------------------------------------------------------------
  test('6. Case ID is generated by backend and client-provided ID is ignored', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        id: 'client_forged_case_12345',
        patientId: 'PAT-002',
      }),
    });

    assert.strictEqual(res.status, 201);
    const body = await res.json();
    assert.notStrictEqual(body.case.id, 'client_forged_case_12345');
    assert.match(body.case.id, /^case_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
  });

  // --------------------------------------------------------------------------
  // 7. createdBy comes from authenticated user
  // --------------------------------------------------------------------------
  test('7. createdBy is derived from req.user.id and cannot be forged by client', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        patientId: 'PAT-003',
        createdBy: 'usr_forged_fake_id',
      }),
    });

    assert.strictEqual(res.status, 201);
    const body = await res.json();
    assert.notStrictEqual(body.case.createdBy, 'usr_forged_fake_id');
    assert.strictEqual(body.case.createdBy, technicianUser.id);
  });

  // --------------------------------------------------------------------------
  // 8. Newly created case has status "created"
  // --------------------------------------------------------------------------
  test('8. Newly created case starts in "created" status', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        patientId: 'PAT-004',
      }),
    });

    assert.strictEqual(res.status, 201);
    const body = await res.json();
    assert.strictEqual(body.case.status, 'created');
    assert.ok(body.case.createdAt);
    assert.ok(body.case.updatedAt);
  });

  test('8b. Client cannot set status to "completed" during creation (rejected 400)', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        patientId: 'PAT-005',
        status: 'completed',
      }),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /status cannot be set during creation/i);
  });

  // --------------------------------------------------------------------------
  // 9. GET /api/cases works for authorized roles
  // --------------------------------------------------------------------------
  test('9. GET /api/cases works for technician, doctor, and admin', async () => {
    // Seed 2 cases
    await CaseModel.create({ patientId: 'PAT-SEED-1', createdBy: technicianUser.id });
    await CaseModel.create({ patientId: 'PAT-SEED-2', createdBy: adminUser.id });

    // Technician
    const techRes = await fetch(`${baseUrl}/api/cases`, {
      headers: { Authorization: `Bearer ${technicianToken}` },
    });
    assert.strictEqual(techRes.status, 200);
    const techBody = await techRes.json();
    assert.strictEqual(techBody.status, 'success');
    assert.strictEqual(techBody.count, 2);
    assert.strictEqual(techBody.cases.length, 2);

    // Doctor
    const docRes = await fetch(`${baseUrl}/api/cases`, {
      headers: { Authorization: `Bearer ${doctorToken}` },
    });
    assert.strictEqual(docRes.status, 200);
    const docBody = await docRes.json();
    assert.strictEqual(docBody.status, 'success');
    assert.strictEqual(docBody.count, 2);

    // Admin
    const admRes = await fetch(`${baseUrl}/api/cases`, {
      headers: { Authorization: `Bearer ${adminToken}` },
    });
    assert.strictEqual(admRes.status, 200);
    const admBody = await admRes.json();
    assert.strictEqual(admBody.status, 'success');
    assert.strictEqual(admBody.count, 2);
  });

  // --------------------------------------------------------------------------
  // 10. GET /api/cases/:id returns an existing case
  // --------------------------------------------------------------------------
  test('10. GET /api/cases/:id returns existing case for authorized user', async () => {
    const created = await CaseModel.create({
      patientId: 'PAT-100',
      createdBy: technicianUser.id,
      notes: 'Initial checkup notes',
    });

    const res = await fetch(`${baseUrl}/api/cases/${created.id}`, {
      headers: { Authorization: `Bearer ${doctorToken}` },
    });

    assert.strictEqual(res.status, 200);
    const body = await res.json();
    assert.strictEqual(body.status, 'success');
    assert.strictEqual(body.case.id, created.id);
    assert.strictEqual(body.case.patientId, 'PAT-100');
    assert.strictEqual(body.case.createdBy, technicianUser.id);
    assert.strictEqual(body.case.status, 'created');
    assert.strictEqual(body.case.notes, 'Initial checkup notes');
  });

  // --------------------------------------------------------------------------
  // 11. GET /api/cases/:id returns 404 for nonexistent case
  // --------------------------------------------------------------------------
  test('11. GET /api/cases/:id returns 404 for nonexistent case', async () => {
    const res = await fetch(`${baseUrl}/api/cases/case_00000000-0000-0000-0000-000000000000`, {
      headers: { Authorization: `Bearer ${technicianToken}` },
    });

    assert.strictEqual(res.status, 404);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.strictEqual(body.code, 404);
    assert.match(body.message, /not found/i);
  });

  // --------------------------------------------------------------------------
  // 12. PATCH /api/cases/:id validates allowed fields
  // --------------------------------------------------------------------------
  test('12. PATCH /api/cases/:id updates allowed metadata (notes, patientId)', async () => {
    const created = await CaseModel.create({
      patientId: 'PAT-200',
      createdBy: technicianUser.id,
      notes: 'Original note',
    });

    const res = await fetch(`${baseUrl}/api/cases/${created.id}`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        notes: 'Updated screening note',
        patientId: 'PAT-200-AMENDED',
      }),
    });

    assert.strictEqual(res.status, 200);
    const body = await res.json();
    assert.strictEqual(body.status, 'success');
    assert.strictEqual(body.case.id, created.id);
    assert.strictEqual(body.case.patientId, 'PAT-200-AMENDED');
    assert.strictEqual(body.case.notes, 'Updated screening note');
    assert.strictEqual(body.case.createdBy, created.createdBy);
  });

  // --------------------------------------------------------------------------
  // 13. Protected fields cannot be arbitrarily changed
  // --------------------------------------------------------------------------
  test('13a. PATCH /api/cases/:id rejects modifying id (400 Bad Request)', async () => {
    const created = await CaseModel.create({
      patientId: 'PAT-300',
      createdBy: technicianUser.id,
    });

    const res = await fetch(`${baseUrl}/api/cases/${created.id}`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ id: 'case_hacked_id' }),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /protected/i);
  });

  test('13b. PATCH /api/cases/:id rejects modifying createdBy (400 Bad Request)', async () => {
    const created = await CaseModel.create({
      patientId: 'PAT-301',
      createdBy: technicianUser.id,
    });

    const res = await fetch(`${baseUrl}/api/cases/${created.id}`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ createdBy: 'usr_hacked_creator' }),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /protected/i);
  });

  test('13c. PATCH /api/cases/:id rejects arbitrary status modification (400 Bad Request)', async () => {
    const created = await CaseModel.create({
      patientId: 'PAT-302',
      createdBy: technicianUser.id,
    });

    const res = await fetch(`${baseUrl}/api/cases/${created.id}`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ status: 'completed' }),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /protected/i);
  });

  test('13d. PATCH /api/cases/:id rejects unknown fields (400 Bad Request)', async () => {
    const created = await CaseModel.create({
      patientId: 'PAT-303',
      createdBy: technicianUser.id,
    });

    const res = await fetch(`${baseUrl}/api/cases/${created.id}`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ aiDiagnosis: 'Proliferative DR' }),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /not allowed for update/i);
  });

  // --------------------------------------------------------------------------
  // 14. Additional edge case tests
  // --------------------------------------------------------------------------
  test('14. PATCH /api/cases/:id with empty body returns 400 Bad Request', async () => {
    const created = await CaseModel.create({
      patientId: 'PAT-400',
      createdBy: technicianUser.id,
    });

    const res = await fetch(`${baseUrl}/api/cases/${created.id}`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({}),
    });

    assert.strictEqual(res.status, 400);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /empty/i);
  });

  test('15. PATCH /api/cases/:id on nonexistent case returns 404 Not Found', async () => {
    const res = await fetch(`${baseUrl}/api/cases/case_00000000-0000-0000-0000-000000000000`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ notes: 'Updating nonexistent' }),
    });

    assert.strictEqual(res.status, 404);
    const body = await res.json();
    assert.strictEqual(body.status, 'error');
    assert.match(body.message, /not found/i);
  });

  test('16. Safe case responses never expose sensitive data or fake AI fields', async () => {
    const res = await fetch(`${baseUrl}/api/cases`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${technicianToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ patientId: 'PAT-SAFE-1' }),
    });

    assert.strictEqual(res.status, 201);
    const body = await res.json();
    const c = body.case;

    // Verify allowed fields exist
    assert.ok(c.id);
    assert.strictEqual(c.patientId, 'PAT-SAFE-1');
    assert.strictEqual(c.createdBy, technicianUser.id);
    assert.strictEqual(c.status, 'created');
    assert.ok(c.createdAt);
    assert.ok(c.updatedAt);

    // Verify forbidden / future fields are NOT exposed
    assert.strictEqual(c.password, undefined);
    assert.strictEqual(c.passwordHash, undefined);
    assert.strictEqual(c.token, undefined);
    assert.strictEqual(c.aiResult, undefined);
    assert.strictEqual(c.gradcam, undefined);
    assert.strictEqual(c.uncertainty, undefined);
    assert.strictEqual(c.diagnosis, undefined);
    assert.strictEqual(c.review, undefined);
  });
});
